#!/usr/bin/env node
/*
 * Adds an Android Macrobenchmark test module only to the Android directory
 * generated by Expo prebuild. The generated directory is git-ignored, so this
 * keeps native measurement plumbing reproducible without committing it.
 */
const fs = require("node:fs");
const path = require("node:path");

const androidDir = process.argv[2]
  ? path.resolve(process.argv[2])
  : path.resolve(__dirname, "..");
const settingsPath = path.join(androidDir, "settings.gradle");
const appManifestPath = path.join(
  androidDir,
  "app",
  "src",
  "main",
  "AndroidManifest.xml",
);
const moduleDir = path.join(androidDir, "macrobenchmark");
const moduleBuildPath = path.join(moduleDir, "build.gradle");
const testDir = path.join(
  moduleDir,
  "src",
  "main",
  "java",
  "com",
  "narqa",
  "ebos",
  "benchmark",
);
const testPath = path.join(testDir, "NarqaMacrobenchmark.kt");
const settingsMarker = "// NARQA_PERFORMANCE_BENCHMARK_MODULE";

for (const requiredPath of [settingsPath, appManifestPath]) {
  if (!fs.existsSync(requiredPath)) {
    throw new Error(
      `Expected generated Android file not found: ${requiredPath}. Run Expo prebuild before configuring performance measurement.`,
    );
  }
}

let settings = fs.readFileSync(settingsPath, "utf8");
if (settings.includes(settingsMarker)) {
  throw new Error(
    "Performance benchmark module is already configured. Refusing to patch the generated Android project twice.",
  );
}
settings = `${settings.trimEnd()}\n\n${settingsMarker}\ninclude ':macrobenchmark'\n`;
fs.writeFileSync(settingsPath, settings, { encoding: "utf8", mode: 0o600 });

let manifest = fs.readFileSync(appManifestPath, "utf8");
if (!manifest.includes('android:shell="true"')) {
  const closingApplication = "</application>";
  if (!manifest.includes(closingApplication)) {
    throw new Error(
      "Expected application closing tag was not found in the generated Android manifest.",
    );
  }
  manifest = manifest.replace(
    closingApplication,
    `    <!-- NARQA_PERFORMANCE_PROFILEABLE: permits shell-only trace capture for benchmark builds. -->\n    <profileable android:shell="true" />\n  ${closingApplication}`,
  );
  fs.writeFileSync(appManifestPath, manifest, { encoding: "utf8", mode: 0o600 });
}

fs.mkdirSync(testDir, { recursive: true, mode: 0o700 });
fs.writeFileSync(
  moduleBuildPath,
  `apply plugin: 'com.android.test'\napply plugin: 'org.jetbrains.kotlin.android'\n\nandroid {\n    namespace 'com.narqa.ebos.macrobenchmark'\n    compileSdk 36\n\n    defaultConfig {\n        minSdk 29\n        targetSdk 36\n        testInstrumentationRunner 'androidx.test.runner.AndroidJUnitRunner'\n    }\n\n    targetProjectPath = ':app'\n    experimentalProperties['android.experimental.self-instrumenting'] = true\n}\n\ndependencies {\n    implementation 'androidx.benchmark:benchmark-macro-junit4:1.5.0'\n    implementation 'androidx.test.ext:junit:1.2.1'\n    implementation 'androidx.test:runner:1.6.2'\n}\n`,
  { encoding: "utf8", mode: 0o600 },
);

fs.writeFileSync(
  testPath,
  `package com.narqa.ebos.benchmark\n\nimport androidx.benchmark.macro.FrameTimingMetric\nimport androidx.benchmark.macro.StartupMode\nimport androidx.benchmark.macro.StartupTimingMetric\nimport androidx.benchmark.macro.junit4.MacrobenchmarkRule\nimport androidx.test.ext.junit.runners.AndroidJUnit4\nimport androidx.test.filters.LargeTest\nimport org.junit.Rule\nimport org.junit.Test\nimport org.junit.runner.RunWith\n\nprivate const val TARGET_PACKAGE = "com.narqa.ebos"\nprivate const val ITERATIONS = 5\n\n/**\n * Measures the app's production-like release APK. Results are stored as JSON\n * and Perfetto traces by AndroidX Benchmark. A CI emulator collects evidence,\n * while acceptance thresholds belong to repeatable physical-device runs.\n */\n@LargeTest\n@RunWith(AndroidJUnit4::class)\nclass NarqaMacrobenchmark {\n    @get:Rule\n    val benchmarkRule = MacrobenchmarkRule()\n\n    @Test\n    fun coldStart() = benchmarkRule.measureRepeated(\n        packageName = TARGET_PACKAGE,\n        metrics = listOf(StartupTimingMetric()),\n        iterations = ITERATIONS,\n        startupMode = StartupMode.COLD,\n        setupBlock = { pressHome() },\n    ) {\n        startActivityAndWait()\n    }\n\n    @Test\n    fun warmStart() = benchmarkRule.measureRepeated(\n        packageName = TARGET_PACKAGE,\n        metrics = listOf(StartupTimingMetric()),\n        iterations = ITERATIONS,\n        startupMode = StartupMode.WARM,\n        setupBlock = { pressHome() },\n    ) {\n        startActivityAndWait()\n    }\n\n    @Test\n    fun homeScreenScrollFrames() = benchmarkRule.measureRepeated(\n        packageName = TARGET_PACKAGE,\n        metrics = listOf(FrameTimingMetric()),\n        iterations = ITERATIONS,\n        startupMode = StartupMode.WARM,\n        setupBlock = { pressHome() },\n    ) {\n        startActivityAndWait()\n        device.waitForIdle()\n        device.swipe(\n            device.displayWidth / 2,\n            device.displayHeight * 3 / 4,\n            device.displayWidth / 2,\n            device.displayHeight / 4,\n            250,\n        )\n        device.waitForIdle()\n    }\n}\n`,
  { encoding: "utf8", mode: 0o600 },
);

console.log(`Configured Android performance measurement at ${moduleDir}`);
